-- Depot > Playbooks (Sean, 2026-11-03): "I need the playbooks to reel me in... what playbook is this being logged into, and where do we stand
-- on that playbook as a whole?" One row per active playbook: its goal, where it stands, the one next action and who owns it.
-- Written from the repo notes (CLAUDE.md) and the playbook records on 2026-11-03; Logan updates the row at every wrap up.
create table if not exists ve_playbook_index (
  slug text primary key,
  brand_slug text not null default 'vegans-explore',
  title text not null,
  goal text not null,
  status text not null default 'building' check (status in ('building','waiting_on_sean','watching','parked','done')),
  stage text not null default '',
  next_action text not null default '',
  owner text not null default 'Logan' check (owner in ('Logan','Sean')),
  due_on date,
  priority int not null default 50,
  updated_at timestamptz not null default now(),
  updated_by uuid
);
alter table ve_playbook_index enable row level security;

insert into ve_playbook_index (slug, brand_slug, title, goal, status, stage, next_action, owner, due_on, priority) values
('ve-abuse-watch','vegans-explore','Abuse watch','Stop people farming points through the free survey door, with Sean as the judge and the system only gathering evidence.','waiting_on_sean','Built and live: the daily scan, Depot > Watchlist, the points freeze, the standing check in 15 functions and the policy wording. Opening cases is still log only.','On Nov 10 read Watchlist > Would flag, then decide whether to turn on opening cases.','Sean','2026-11-10',1),
('ve-pathways','vegans-explore','Three doors and campaigns on people','Anyone gets in by email, the survey or the $11, and every person we reach sits in a campaign with a next step.','building','Locked 2026-11-03. The survey door is built. Left, in order: Pulse subscribe, the people sender, the updated Welcome, profiles with groups, campaign homes.','Build Pulse subscribe: a box on every Pulse page, an exit pop-up once per visitor, double opt-in.','Logan',null,2),
('ve-door-guides','vegans-explore','Door Guides','Free Guides unlock with an email; the $11 Passport unlocks your voice.','waiting_on_sean','Step 1 is live: the Events Guide is free with an email. Two welcome notes are drafted and switched off.','Sean approves the wording of the two welcome notes and switches them on. Then watch 30 days of numbers before the other three Guides.','Sean','2026-12-03',3),
('ve-pricing-points-passport','vegans-explore','Earn your Passport and points','People can earn their membership by taking part now, not only by paying.','building','Parts 1 to 5 are built and live: the check-in menu, Challenge stops and the Vault, the Taster account, the three challenges, the emails. Left: 6 the content gig, 7 the business points rule.','Decide with Sean whether the three doors retire the challenges, before building 6 and 7.','Sean',null,4),
('ve-event-host-path','vegans-explore','Event host path','Every event we list brings its host in: claim it, then tickets, sponsorship and ads.','waiting_on_sean','Steps 1 (the event claim) and 2 (the heads-up email) are built. The email is a draft and sends nothing until approved.','Sean approves the heads-up email once. Then step 3, per-event ticketing.','Sean',null,5),
('ve-front-of-house','vegans-explore','BrandDesk: managed marketing for Vegan businesses','A $1,500 setup and $500 a month service that gives a Vegan business a real brand presence.','waiting_on_sean','The whole product is built and live: checkout, onboarding, Library, website launch, visits, check-ins, rotation, social phase 1 and the pitch pages. No client yet. Checkout opens only for listings Sean opens.','Sean picks the pilot (the business that asked, plus two in South Florida) and opens their checkout.','Sean',null,6),
('ve-group-partners','vegans-explore','Group Partners','Community groups run their community and events on Vegans Explore and bring us members.','waiting_on_sean','Built end to end: the sample group, tickets, guest pass, gifts, applications, earnings. No invitations go out until Sean has reviewed the program.','Sean reviews the program and picks the first groups to invite.','Sean',null,7),
('ve-nonprofit-partners','vegans-explore','Nonprofit Partners and Guide','Nonprofits, rescues and sanctuaries partner with us and earn from the link.','waiting_on_sean','Built and live, and the Nonprofit Guide is launched.','Send Susan Hargreaves (Animal Hero Kids) her invitation when Sean is ready.','Sean',null,8),
('ve-money-in','vegans-explore','Money in and revenue','See every payment as it arrives and the revenue on the dashboard.','watching','Payment emails and the Revenue module are live. Client services are shown apart.','Sean decides how to move Brooke Sellers'' billing to the LESARUSS Stripe account before her Nov 30 charge.','Sean','2026-11-30',9),
('ve-universal-search','vegans-explore','Universal search and the question queue','One search box that answers with listings, content and stores, and learns from what it cannot answer.','watching','Built: the box on every page, places and a worldwide gazetteer, content, stores, Liz and the search question queue.','Logan works the search question queue daily. Next to build: Events, Guides, recipes and the Pulse in the results.','Logan',null,10),
('ve-outreach-buckets','vegans-explore','Daily outreach (Depot > Outreach)','Everyone Sean knows is reached by November 30, one message at a time, from one daily list.','building','The day view, messages, email sending and templates are built. 20 messages loaded.','Build Results by bucket and week (opened, clicked, replied, joined).','Logan','2026-11-30',11),
('ve-ambassadors-talent-shop','vegans-explore','Ambassadors, creators and the shop','One Ambassador program where people climb by results, plus a Gig Board and a shop of services.','building','The door, the Official Creator Guide, the Gig Board, creator applications and the paid-work checklist are built.','Post gigs with the new fields and decide applicants from Depot > Bounties (not built yet).','Logan',null,12),
('ve-events-guide','vegans-explore','Vegan Events Guide','A Guide for anyone hosting a Vegan event, and the top of the organizer funnel.','building','Built, not launched. Sponsorship intake, host stories and venues are in.','Launch checklist: Guide tab mapping for Event Venues and Community > Events, River''s lines, then turn indexing on.','Logan',null,13),
('branddesk-production-wing','lesaruss-hq','BrandDesk in HQ (the production wing)','One desk where every brand has a locked brand kit and a plan that rolls out dated work.','building','Built: Partner checkout, Studio renamed, brand kit foundation, Websites, plan engine, Social room. Only the Vegans Explore kit is launched.','Start the Sean A. Russell and GeekFon Society brand kits so they can have plans.','Logan',null,14),
('ve-supermarket-guide','vegans-explore','Supermarket Guide','Supermarkets sponsor it so members can find Vegan items aisle by aisle.','parked','Built, prelaunch, members only. Publix is the example (731 stores in three Florida chapters).','Nothing to build until a supermarket sponsors. Sean approaches Publix first.','Sean',null,20),
('ve-store-scan-search','vegans-explore','Scan and store search','Scan an item in a store and see if it is Vegan, where it is and who carries it.','parked','Search, scan, location-checked sightings and the chain registry are built.','Wait for a sponsoring chain. Left: scan as a Taste slide, a sponsor multiplier, other chains.','Logan',null,21),
('ve-member-profiles-partner-windows','vegans-explore','Member profiles and partner windows','Members choose what is in their profile; we choose when it is seen.','watching','Phases 1 to 3 are built (switches, the event window, the campaign window).','Review how the first windows ran, then decide phase 4, one message to past guests.','Sean',null,22),
('ve-listing-check','vegans-explore','Listing check and Directory health','Keep the Directory honest: closed places off, open places back, owners told what to fix.','watching','Live and free on claim. Nightly and weekly checks run on their own.','Work the Needs support list in Directory review as it fills.','Logan',null,23),
('ve-social-studio','vegans-explore','Depot > Social','See and approve what is scheduled for every brand, and how it did.','watching','Plan, Notes, Music, stories and analytics are built and in use.','No build waiting. Podcast downloads from Captivate are not built.','Logan',null,24),
('ve-content-index','vegans-explore','Content index','Ten years of episodes searchable by topic, with the exact second to play.','watching','Transcripts, moments by topic and search are built. Sean keeps dropping transcript files.','Match each new batch of transcripts. Not built: members'' search and Guides playing moments.','Logan',null,25),
('ve-venue-guides','vegans-explore','Stadium and Airport Guides','Venue Guides where members keep the Vegan items accurate for points.','watching','Both launched, with maps and first-to-confirm bounties.','Queued, not built: /bounties as one list, evergreen and paid bounties.','Logan',null,26),
('ve-local-food-products','vegans-explore','Local Food and Products','Local Food shows everything here; Products are what you can buy anywhere.','done','Built 2026-11-01 and filled with brands.','None.','Logan',null,90),
('ve-nutrition-guide','vegans-explore','Nutrition Guide','A Guide for Vegan nutrition, with Theo.','done','Launched 2026-10-31.','None.','Logan',null,91)
on conflict (slug) do nothing;

-- The index's own record (playbook ve-playbook-index) and its row. Data only, safe to run twice.
insert into public.playbook_records (slug, brand_slug, author, body, source, kind)
select 've-playbook-index', 'vegans-explore', 'Logan',
 $q$DECISION 2026-11-03 (Sean: "I need the playbooks to reel me in... what playbook is this being logged into, and where do we stand on that playbook as a whole?"): Depot > Playbooks (/admin/depot/playbooks, first in the Go to menu; table ve_playbook_index, edge function ve-playbooks). One row per active playbook: goal, where it stands, the one next action, who owns it, a due date. Every chat opens by naming the playbook the work belongs to. Wrap up updates that playbook's row. A playbook with records but no row shows under Not in the index until it is added or left as history. Seeded 2026-11-03 with 23 Vegans Explore and BrandDesk playbooks from the repo notes.$q$,
 'text', 'decision'
where not exists (select 1 from public.playbook_records where slug = 've-playbook-index');

insert into ve_playbook_index (slug, brand_slug, title, goal, status, stage, next_action, owner, priority)
values ('ve-playbook-index','vegans-explore','Depot > Playbooks (this index)','Every chat starts from the active playbooks, so work answers to a playbook and not to the latest idea.','watching','Built 2026-11-03 and seeded with 23 playbooks.','Update the row of the playbook worked on at every wrap up. Add playbooks from Not in the index as they come up.','Logan',27)
on conflict (slug) do nothing;
